//! Mongolian inflection, learned from Wiktionary.
//!
//! Generated by morphe from the Kaikki Mongolian dump of 2026-10-03. Do not edit.
//! Every function is total: unknown words are inflected by prediction, and
//! the `_scored` versions give every candidate with a confidence, best first.
//! Variant confidences reflect Wiktionary's listing order, not measured usage.
//!
//! Data: Wiktionary contributors, CC BY-SA 4.0, via kaikki.org.

#![forbid(unsafe_code)]

pub use morphe::{Options, Scored};
use std::sync::OnceLock;

static DATA: &[u8] = include_bytes!("model.bin");

/// The trained model, for dynamic queries.
pub fn model() -> Option<&'static morphe::Model> {
    static MODEL: OnceLock<Option<morphe::Model>> = OnceLock::new();
    MODEL.get_or_init(|| morphe::Model::decode(DATA)).as_ref()
}

fn best(scored: Scored<String>, word: &str) -> String {
    scored.into_iter().next().map_or_else(|| word.split(',').next().unwrap_or(word).trim().to_string(), |x| x.0)
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Case {
    Nominative,
    Genitive,
    Accusative,
    DativeLocative,
    Ablative,
    Instrumental,
    Comitative,
    Privative,
    Directive,
    Substantive,
}

impl Case {
    pub const ALL: [Self; 10] = [Self::Nominative, Self::Genitive, Self::Accusative, Self::DativeLocative, Self::Ablative, Self::Instrumental, Self::Comitative, Self::Privative, Self::Directive, Self::Substantive];
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub enum Number {
    Singular,
    Plural,
}

impl Number {
    pub const ALL: [Self; 2] = [Self::Singular, Self::Plural];
}

/// Settings for systematic choices. `Mongolian::default()` is what the free functions use.
#[derive(Clone, Copy, Debug, Default)]
pub struct Mongolian {
    pub options: Options,
}

impl Mongolian {
    /// Keep stress and similar marks in the output (on by default).
    pub fn marks(mut self, on: bool) -> Self {
        self.options.marks = on;
        self
    }

    /// A noun form.
    pub fn noun_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(0),
            (Case::Nominative, Number::Plural,) => Some(1),
            (Case::Genitive, Number::Singular,) => Some(2),
            (Case::Genitive, Number::Plural,) => Some(3),
            (Case::Accusative, Number::Singular,) => Some(4),
            (Case::Accusative, Number::Plural,) => Some(5),
            (Case::DativeLocative, Number::Singular,) => Some(6),
            (Case::DativeLocative, Number::Plural,) => Some(7),
            (Case::Ablative, Number::Singular,) => Some(8),
            (Case::Ablative, Number::Plural,) => Some(9),
            (Case::Instrumental, Number::Singular,) => Some(10),
            (Case::Instrumental, Number::Plural,) => Some(11),
            (Case::Comitative, Number::Singular,) => Some(12),
            (Case::Comitative, Number::Plural,) => Some(13),
            (Case::Privative, Number::Singular,) => Some(14),
            (Case::Privative, Number::Plural,) => Some(15),
            (Case::Directive, Number::Singular,) => Some(16),
            (Case::Directive, Number::Plural,) => Some(17),
            (Case::Substantive, Number::Singular,) => Some(18),
            (Case::Substantive, Number::Plural,) => Some(19),
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form. The best candidate; the word itself if nothing is known.
    pub fn noun(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_scored(word, case, number), word)
    }

    /// A noun form (reflexive).
    pub fn noun_reflexive_scored(&self, word: &str, case: Case, number: Number) -> Scored<String> {
        let cell: Option<u32> = match (case, number,) {
            (Case::Nominative, Number::Singular,) => Some(20),
            (Case::Nominative, Number::Plural,) => Some(21),
            (Case::Genitive, Number::Singular,) => Some(22),
            (Case::Genitive, Number::Plural,) => Some(23),
            (Case::Accusative, Number::Singular,) => Some(24),
            (Case::Accusative, Number::Plural,) => Some(25),
            (Case::DativeLocative, Number::Singular,) => Some(26),
            (Case::DativeLocative, Number::Plural,) => Some(27),
            (Case::Ablative, Number::Singular,) => Some(28),
            (Case::Ablative, Number::Plural,) => Some(29),
            (Case::Instrumental, Number::Singular,) => Some(30),
            (Case::Instrumental, Number::Plural,) => Some(31),
            (Case::Comitative, Number::Singular,) => Some(32),
            (Case::Comitative, Number::Plural,) => Some(33),
            (Case::Privative, Number::Singular,) => Some(34),
            (Case::Privative, Number::Plural,) => Some(35),
            (Case::Directive, Number::Singular,) => Some(36),
            (Case::Directive, Number::Plural,) => Some(37),
            _ => None,
        };
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// A noun form (reflexive). The best candidate; the word itself if nothing is known.
    pub fn noun_reflexive(&self, word: &str, case: Case, number: Number) -> String {
        best(self.noun_reflexive_scored(word, case, number), word)
    }

    /// The attributive noun.
    pub fn noun_attributive_scored(&self, word: &str) -> Scored<String> {
        let cell: Option<u32> = Some(38);
        match (model(), cell) {
            (Some(m), Some(c)) => m.inflect(0, c, word, self.options),
            _ => Vec::new(),
        }
    }

    /// The attributive noun. The best candidate; the word itself if nothing is known.
    pub fn noun_attributive(&self, word: &str) -> String {
        best(self.noun_attributive_scored(word), word)
    }

    /// Dictionary spelling of a noun (with stress marks where the data has them).
    pub fn noun_lemma(&self, word: &str) -> String {
        model().and_then(|m| m.lemma(0, word)).unwrap_or_else(|| word.to_string())
    }

}

